def broken_calc(start_value: int, target: int) -> int:
    steps = 0
    while target > start_value:
        # reverse the last forward move
        if target % 2 == 1:
            target += 1
        else:
            target //= 2
        steps += 1
    return steps + (start_value - target)

def min_wasted_space(packages: list[int], boxes: list[list[int]]) -> int:
    MOD = 10 ** 9 + 7
    packages = sorted(packages)
    n = len(packages)
    biggest = packages[-1]
    best = None
    for sizes in boxes:
        sizes = sorted(sizes)
        if sizes[-1] < biggest:
            continue  # this supplier cannot fit every package
        used = 0  # total size of all boxes chosen
        prev = 0
        for b in sizes:
            j = bisect.bisect_right(packages, b)
            used += (j - prev) * b  # packages in (previous size, b]
            prev = j
            if prev == n:
                break
        if best is None or used < best:
            best = used
    if best is None:
        return -1
    return (best - sum(packages)) % MOD

def put_marbles(weights: list[int], k: int) -> int:
    # each cut between i and i + 1 adds this pair to the score
    pairs = sorted(weights[i] + weights[i + 1] for i in range(len(weights) - 1))
    cuts = k - 1
    if cuts == 0:
        return 0
    return sum(pairs[-cuts:]) - sum(pairs[:cuts])

