def len_longest_fib_subseq(arr: list[int]) -> int:
    n = len(arr)
    index = {v: i for i, v in enumerate(arr)}
    dp = [[2] * n for _ in range(n)]  # dp[j][k]: longest ending with arr[j], arr[k]
    best = 0
    for k in range(2, n):
        ak = arr[k]
        for j in range(k - 1, 0, -1):
            prev = ak - arr[j]
            if prev >= arr[j]:
                break  # earlier j only make prev larger
            i = index.get(prev)
            if i is not None:
                length = dp[i][j] + 1
                dp[j][k] = length
                if length > best:
                    best = length
    return best

