def minimum_hamming_distance(source: list[int], target: list[int], allowed_swaps: list[list[int]]) -> int:
    n = len(source)
    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving
            x = parent[x]
        return x

    for a, b in allowed_swaps:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    available = defaultdict(Counter)  # group root -> source values in it
    roots = [find(i) for i in range(n)]
    for i in range(n):
        available[roots[i]][source[i]] += 1
    distance = 0
    for i in range(n):
        bag = available[roots[i]]
        if bag[target[i]] > 0:
            bag[target[i]] -= 1  # matched within the group
        else:
            distance += 1
    return distance

