def diagonal_sort(mat: list[list[int]]) -> list[list[int]]:
    rows, cols = len(mat), len(mat[0])
    groups = defaultdict(list)          # i - j -> values on that diagonal
    for i in range(rows):
        for j in range(cols):
            groups[i - j].append(mat[i][j])
    for values in groups.values():
        values.sort(reverse=True)       # pop() then yields the smallest first
    result = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            result[i][j] = groups[i - j].pop()
    return result

def unique_paths_iii(grid: list[list[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    to_visit = 0
    start = (0, 0)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != -1:
                to_visit += 1
            if grid[r][c] == 1:
                start = (r, c)

    def walk(r: int, c: int, remaining: int) -> int:
        # remaining counts the unvisited open cells, including (r, c)
        if grid[r][c] == 2:
            return 1 if remaining == 1 else 0
        saved = grid[r][c]
        grid[r][c] = -1                       # mark visited
        total = 0
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != -1:
                total += walk(nr, nc, remaining - 1)
        grid[r][c] = saved                    # undo
        return total

    return walk(start[0], start[1], to_visit)

def maximum_gain(s: str, x: int, y: int) -> int:
    def strip(text: str, first: str, second: str, points: int):
        """Remove every possible first+second pair; return (score, leftover text)."""
        stack, score = [], 0
        for ch in text:
            if ch == second and stack and stack[-1] == first:
                stack.pop()
                score += points
            else:
                stack.append(ch)
        return score, stack

    if x >= y:
        gained, rest = strip(s, "a", "b", x)
        more, _ = strip(rest, "b", "a", y)
    else:
        gained, rest = strip(s, "b", "a", y)
        more, _ = strip(rest, "a", "b", x)
    return gained + more

def num_of_minutes(n: int, headID: int, manager: list[int], informTime: list[int]) -> int:
    reports = [[] for _ in range(n)]
    for emp, boss in enumerate(manager):
        if boss != -1:
            reports[boss].append(emp)
    longest = 0
    queue = deque([(headID, 0)])   # (employee, minute they hear the news)
    while queue:
        emp, heard = queue.popleft()
        longest = max(longest, heard)
        done = heard + informTime[emp]   # when this employee's reports hear it
        for sub in reports[emp]:
            queue.append((sub, done))
    return longest

