        self._it = iterator
        self._has_cached = iterator.hasNext()
        self._cached = iterator.next() if self._has_cached else None

    def peek(self):
        return self._cached

    def next(self):
        value = self._cached
        # Read one element ahead so peek() stays O(1).
        self._has_cached = self._it.hasNext()
        self._cached = self._it.next() if self._has_cached else None
        return value

    def hasNext(self):
