def incremovable_subarray_count(nums: list[int]) -> int:
    n = len(nums)
    i = 0
    while i + 1 < n and nums[i] < nums[i + 1]:
        i += 1                      # nums[0..i] is the longest increasing prefix
    if i == n - 1:
        return n * (n + 1) // 2     # removing anything keeps it increasing
    total = i + 2                   # removals that run to the end: keep a prefix of length 0..i+1
    j = n - 1                       # kept suffix starts at j
    while j > 0:
        # Shrink the usable prefix so its last value is below nums[j].
        while i >= 0 and nums[i] >= nums[j]:
            i -= 1
        total += i + 2              # prefix lengths 0..i+1
        if nums[j - 1] >= nums[j]:
            break                   # the suffix cannot extend further left
        j -= 1
    return total

