def maximum_removals(s: str, p: str, removable: list[int]) -> int:
    m = len(removable)
    removed_at = [m] * len(s)          # step at which each index disappears
    for step, idx in enumerate(removable):
        removed_at[idx] = step

    def still_subsequence(k: int) -> bool:
        j = 0
        for i, ch in enumerate(s):
            if removed_at[i] >= k and ch == p[j]:
                j += 1
                if j == len(p):
                    return True
        return False

    low, high = 0, m                   # answer lies in [low, high]
    while low < high:
        mid = (low + high + 1) // 2
        if still_subsequence(mid):
            low = mid
        else:
            high = mid - 1
    return low

