def min_abs_difference(nums: List[int], goal: int) -> int:
    def subset_sums(arr: List[int]) -> List[int]:
        sums = {0}
        for x in arr:
            sums |= {s + x for s in sums}     # a set keeps repeated sums from piling up
        return sorted(sums)

    half = len(nums) // 2
    left = subset_sums(nums[:half])
    right = subset_sums(nums[half:])
    best = abs(goal)                      # the empty subsequence
    i, j = 0, len(right) - 1
    while i < len(left) and j >= 0:
        total = left[i] + right[j]
        diff = total - goal
        if diff == 0:
            return 0
        if abs(diff) < best:
            best = abs(diff)
        if diff < 0:
            i += 1                        # need a larger sum
        else:
            j -= 1                        # need a smaller sum
    return best

