def valid_utf8(data: List[int]) -> bool:
    remaining = 0                       # continuation bytes still expected
    for value in data:
        byte = value & 0xFF
        if remaining == 0:
            if byte >> 7 == 0:
                continue                # 0xxxxxxx: one byte character
            elif byte >> 5 == 0b110:
                remaining = 1
            elif byte >> 4 == 0b1110:
                remaining = 2
            elif byte >> 3 == 0b11110:
                remaining = 3
            else:
                return False            # 10xxxxxx or 11111xxx cannot start a character
        else:
            if byte >> 6 != 0b10:
                return False            # expected a continuation byte
            remaining -= 1
    return remaining == 0

