def min_height_shelves(books: List[List[int]], shelf_width: int) -> int:
    n = len(books)
    dp = [0] + [float("inf")] * n         # dp[i]: best height for the first i books
    for i in range(1, n + 1):
        width = tallest = 0
        j = i - 1
        # Try putting books j..i-1 together on the last shelf.
        while j >= 0:
            thickness, height = books[j]
            width += thickness
            if width > shelf_width:
                break
            if height > tallest:
                tallest = height
            if dp[j] + tallest < dp[i]:
                dp[i] = dp[j] + tallest
            j -= 1
    return dp[n]

