def minimum_cost(n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]    # path halving
            x = parent[x]
        return x

    for u, v, _ in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            if size[ru] < size[rv]:
                ru, rv = rv, ru
            parent[rv] = ru
            size[ru] += size[rv]

    ALL_ONES = (1 << 17) - 1                 # covers every weight up to 10^5
    cost = [ALL_ONES] * n                    # AND of all edges in each component (at its root)
    for u, _, w in edges:
        r = find(u)
        cost[r] &= w

    answers = []
    for s, t in query:
        rs, rt = find(s), find(t)
        answers.append(cost[rs] if rs == rt else -1)
    return answers

